provenance.sourcePrompt:
Opening title card. 6s, 1920x1080, SILENT. Full-screen portrait photo, Ken Burns push. Dark overlay.. No eyebrow line, no sub line — name only. Masked reveal (overflow:hidden + clip-path:inset(0)). Exits with reverse mask then fade to black
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@900&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
html,body{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{position:relative;width:1920px;height:1080px;overflow:hidden;background:#000;}
#bg{
position:absolute;top:0;left:0;width:100%;height:100%
object-fit:cover;object-position:center;z-index:1
transform-origin:50% 40%
animation:kb 6s linear forwards
}
@keyframes kb{from{transform:scale(1.0);}to{transform:scale(1.05);}}
#overlay{position:absolute;top:0;left:0;right:0;bottom:0;z-index:2;background:rgba(5,6,10,0.48);pointer-events:none;}
#grad{
position:absolute;bottom:0;left:0;width:100%;height:100%;z-index:3
background:linear-gradient(160deg,rgba(0,0,0,0.72) 0%,rgba(0,0,0,0.40) 35%,transparent 65%)
pointer-events:none
}
#textblock{position:absolute;bottom:88px;left:88px;z-index:10;}
ml{display:block;overflow:hidden;clip-path:inset(0);line-height:1.0;margin-bottom:4px;}
ml span{display:block;transform:translateY(105%);opacity:0;will-change:transform,opacity;}
ml-a span,.ml-b span{
font-family:'Inter',Arial,sans-serif
font-size:100px;font-weight:900
letter-spacing:-.025em;text-transform:uppercase
color:#f0ece4;line-height:.92
}
#fade{position:absolute;top:0;left:0;right:0;bottom:0;z-index:50;background:#000;opacity:0;pointer-events:none;}
</style>
</head>
<body>
<div id="scene">
<img id="bg" src="{{heroImg}}" alt="">
<div id="overlay"></div>
<div id="grad"></div>
<div id="fade"></div>
<div id="textblock">
<div class="ml ml-a" id="la"><span>Benedict</span></div>
<div class="ml ml-b" id="lb"><span>Cumberbatch</span></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
tl.to('#la span',{y:0,opacity:1,duration:0.7,ease:'power4.out'},0.35)
tl.to('#lb span',{y:0,opacity:1,duration:0.7,ease:'power4.out'},0.50)
tl.to('#lb span',{y:'105%',opacity:0,duration:0.42,ease:'power2.in'},4.9)
tl.to('#la span',{y:'105%',opacity:0,duration:0.42,ease:'power2.in'},5.02)
tl.to('#fade',{opacity:1,duration:0.5,ease:'power2.inOut'},5.15)
tl.set('#fade',{opacity:1},5.75)
})
</script>
</body>
</html>
```
